import { Suspense } from 'react'
import { RevenueChart } from './RevenueChart'
import { LatestInvoices } from './LatestInvoices'
import { CardStats } from './CardStats'

async function getCardStats() {
  const res = await fetch('https://api.example.com/dashboard/stats')
  return res.json()
}

async function getRevenue() {
  const res = await fetch('https://api.example.com/dashboard/revenue')
  return res.json()
}

async function getInvoices() {
  const res = await fetch('https://api.example.com/dashboard/invoices')
  return res.json()
}

async function CardStatsSection() {
  const data = await getCardStats()

  return (
    <CardStats
      totalRevenue={data.totalRevenue}
      totalInvoices={data.totalInvoices}
    />
  )
}

async function RevenueChartSection() {
  const revenue = await getRevenue()

  return <RevenueChart revenue={revenue} />
}

async function LatestInvoicesSection() {
  const invoices = await getInvoices()

  return <LatestInvoices invoices={invoices} />
}

export default function Page() {
  return (
    <main>
      <h1>Dashboard</h1>
      <Suspense
        fallback={
          <div className="grid grid-cols-2 gap-4">
            <div className="card">Loading revenue...</div>
            <div className="card">Loading invoices...</div>
          </div>
        }
      >
        <CardStatsSection />
      </Suspense>
      <Suspense fallback={<div className="chart">Loading chart...</div>}>
        <RevenueChartSection />
      </Suspense>
      <Suspense fallback={<div className="invoices">Loading invoices...</div>}>
        <LatestInvoicesSection />
      </Suspense>
    </main>
  )
}

